missing = [k for k in T if len(T[k]) != len(LANGS)]
if missing:
    raise SystemExit("wrong number of translations: " + ", ".join(missing))


def opt(entry):
    kind = entry[0]
    if kind == "title":
        return {"text": f"CHIM Vampire Bridge {VERSION} by SaurOff", "type": "header"}
    if kind == "header":
        return {"text": "$COV_" + entry[1], "type": "header"}
    _, oid, key = entry[:3]
    e = {"id": oid, "text": "$COV_" + key, "type": "slider" if kind == "fslider" else kind, "help": "$COV_" + key + "H"}
    if kind == "toggle":
        e["valueOptions"] = {"sourceType": "ModSettingBool"}
    elif kind == "input":
        e["valueOptions"] = {"sourceType": "ModSettingString"}
    else:
        lo, hi, step, fmt = entry[3:]
        e["valueOptions"] = {"min": lo, "max": hi, "step": step, "formatString": fmt,
                             "sourceType": "ModSettingFloat" if kind == "fslider" else "ModSettingInt"}
    return e


cfg = {"modName": "CHIMVampireBridge", "displayName": "CHIM Vampire Bridge", "minMcmVersion": 9,
       "cursorFillMode": "topToBottom",
       "pages": [{"pageDisplayName": "$COV_" + page, "cursorFillMode": "topToBottom", "content": [opt(e) for e in entries]}
                 for page, entries in MENU]}
used = {e["text"][5:] for p in cfg["pages"] for e in p["content"] if e["text"].startswith("$COV_")}
used |= {e["help"][5:] for p in cfg["pages"] for e in p["content"] if "help" in e}
used |= {p["pageDisplayName"][5:] for p in cfg["pages"]}
if used - set(T):
    raise SystemExit("no text for: " + ", ".join(sorted(used - set(T))))
os.makedirs(os.path.join(ROOT, "mcm", "translations"), exist_ok=True)
json.dump(cfg, open(os.path.join(ROOT, "mcm", "config.json"), "w", encoding="utf-8", newline="\n"), indent=4, ensure_ascii=False)

out = os.path.join(ROOT, "mcm", "translations")
for i, lang in enumerate(LANGS):
    body = "\r\n".join(f"$COV_{k}\t{v[i]}".replace("\n", " ") for k, v in T.items()) + "\r\n"
    with open(os.path.join(out, f"CHIMVampireBridge_{lang}.txt"), "wb") as f:
        f.write(b"\xff\xfe" + body.encode("utf-16-le"))
FALLBACK_TO_ENGLISH = ["TURKISH", "KOREAN", "DUTCH", "HUNGARIAN", "GREEK", "SWEDISH", "DANISH",
                       "NORWEGIAN", "FINNISH", "ROMANIAN", "BULGARIAN", "SERBIAN", "CROATIAN",
                       "SLOVAK", "ARABIC", "HEBREW", "THAI", "VIETNAMESE", "INDONESIAN",
                       "BRAZILIAN", "PTBR", "LATAM", "MEXICAN", "TRADITIONAL_CHINESE", "CHINESE_TRADITIONAL"]
english = open(os.path.join(out, "CHIMVampireBridge_ENGLISH.txt"), "rb").read()
for lang in FALLBACK_TO_ENGLISH:
    with open(os.path.join(out, f"CHIMVampireBridge_{lang}.txt"), "wb") as f:
        f.write(english)
print(f"{len(T)} strings x {len(LANGS)} languages, {len(FALLBACK_TO_ENGLISH)} English fallbacks; mcm/config.json written")
